   const body=d.createElement('div'),title=text('strong',card.label||'Saved card'),meta=text('small',[card.brand,card.last4?'•••• '+card.last4:'',card.expMonth&&card.expYear?card.expMonth+'/'+card.expYear:''].filter(Boolean).join(' · '));
